INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Projektleiter eine Schlüsselrolle im Projektmanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Steuert das Projekt"}, {"text": "Nein", "correct": false, "because": "Er ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt der Projektleiter?', 3, '[{"text": "Projektziele erfolgreich umsetzen", "correct": true, "because": "Leitet Team und Plan"}, {"text": "Projekt finanzieren", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Anforderungen definieren", "correct": false, "because": "Auftraggeberaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Projektleiter koordiniert das Team. b) Er legt die Ziele allein fest.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Auftraggeber definiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt der Projektleiter?', 4, '[{"text": "Planung überwachen", "correct": true, "because": "Sichert Zeitplan"}, {"text": "Unklare Anweisungen geben", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Team koordinieren", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Fortschritt kontrollieren", "correct": true, "because": "Steuert Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Projektleiter erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Steuerung fehlt"}, {"text": "Ja", "correct": false, "because": "Chaos droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Projektleiter in der Durchführung?', 3, '[{"text": "Koordination und Überwachung", "correct": true, "because": "Sichert Umsetzung"}, {"text": "Ziele neu definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Projekt finanzieren", "correct": false, "because": "Auftraggeberaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Projektleiter nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen Steuerung"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortung hat der Projektleiter?', 3, '[{"text": "Termine und Budget einhalten", "correct": true, "because": "Steuert Ressourcen"}, {"text": "Anforderungen allein festlegen", "correct": false, "because": "Auftraggeberaspekt"}, {"text": "Team extern finanzieren", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Projektleiter kommuniziert mit Stakeholdern. b) Er arbeitet isoliert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Zusammenarbeit nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Projektleiter?', 3, '[{"text": "Unkoordinierte Umsetzung", "correct": true, "because": "Führung fehlt"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Ineffizienz möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Projektleiter ohne Planung arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Plan ist Basis"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Aufgabe des Projektleiters?', 3, '[{"text": "Team-Meeting zur Fortschrittskontrolle", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas steuern", "correct": false, "because": "Zu vage"}, {"text": "Team soll allein arbeiten", "correct": false, "because": "Keine Führung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Projektleiter nur für die Durchführung zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Planung und Abschluss"}, {"text": "Ja", "correct": false, "because": "Projektweite Verantwortung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fähigkeiten braucht der Projektleiter?', 4, '[{"text": "Kommunikation", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Unklare Anweisungen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Führung", "correct": true, "because": "Steuert Team"}, {"text": "Planung", "correct": true, "because": "Sichert Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Projektleiter dokumentieren?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis und Steuerung"}, {"text": "Nein", "correct": false, "because": "Dokumentation wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Projektleiter im Controlling?', 3, '[{"text": "Fortschritt überwachen", "correct": true, "because": "Passt Plan an"}, {"text": "Projektziele neu setzen", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Team finanzieren", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Projektleiter ohne Team arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Team ist Umsetzungsbasis"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Arbeit des Projektleiters?', 3, '[{"text": "Unklare Kommunikation", "correct": true, "because": "Verhindert Koordination"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Steuerung"}, {"text": "Gute Ressourcen", "correct": false, "because": "Unterstützt Arbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Projektleiter steuert Risiken. b) Er ist nur für technische Aufgaben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Projektleiters?', 3, '[{"text": "Zielgerichtete Projektsteuerung", "correct": true, "because": "Fördert Erfolg"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Koordination", "correct": false, "because": "Fördert Zusammenarbeit"}]');
